"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["78557"],{19944(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.criterio_desempate.ordem_invalida","status":422,"titulo":"A ordem do crit\xe9rio de desempate deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.criterio_desempate.ordem_invalida","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["Um dos crit\xe9rios de desempate do corpo do pedido informou `ordem` menor ou igual a\\nzero. A ordem carrega o refinamento sequencial da lista de crit\xe9rios: o\\nprimeiro desempata o grupo inteiro empatado na nota; o segundo desempata s\xf3\\nquem continuar empatado depois do primeiro; e assim por diante. Um valor\\nzero ou negativo n\xe3o tem posi\xe7\xe3o v\xe1lida nessa sequ\xeancia.","Esta confer\xeancia roda numa primeira passada, sobre **todos** os crit\xe9rios do\\ncorpo do pedido, antes de qualquer consulta ao cat\xe1logo de regras (`rol_de_regras`)\\n\u2014 n\xe3o depende de nenhuma resolu\xe7\xe3o cross-m\xf3dulo. Um corpo do pedido com dois\\ncrit\xe9rios de ordem inv\xe1lida devolve as duas viola\xe7\xf5es juntas no array\\n`errors[]` do corpo de erro, cada item com seu `field`\\n(`criterios[<\xedndice>].ordem`).","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada crit\xe9rio de desempate a partir do que foi\\ncongelado \u2014 a mesma confer\xeancia roda de novo. Diferente da passada de forma\\ndo comando, nessa leitura a primeira viola\xe7\xe3o encontrada interrompe a\\nleitura inteira, sem acumular com outras."],"comoResolver":["Informe uma `ordem` positiva para cada crit\xe9rio de desempate do corpo do pedido. Se\\na resposta trouxer mais de uma viola\xe7\xe3o no array `errors[]`, corrija todas\\nantes de reenviar.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema n\xe3o est\xe1 no que\\nfoi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada. Isso indica uma\\ninconsist\xeancia nessa vers\xe3o; abra uma investiga\xe7\xe3o em vez de tentar\\ncorrigir pelo envio."],"ondeAparece":["Defini\xe7\xe3o de crit\xe9rios de desempate do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Criterio desempate"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);